// Para cada espaço ativo, calcula "desde quando" buscar mensagens.
// Regra: olhamos no máximo os últimos 3 dias, e nunca antes da data em que
// o espaço foi ligado (coluna ultima_leitura). Assim ele não lê o histórico inteiro sem querer.
const tresDiasAtras = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000);
const saida = [];

for (const item of $input.all()) {
  const e = item.json;
  if (!e.space_id) continue; // linha vazia (tabela sem espaços)

  let desde = tresDiasAtras;
  if (e.ultima_leitura) {
    const d = new Date(e.ultima_leitura);
    if (d > desde) desde = d; // espaço ligado há menos de 3 dias
  }

  saida.push({ json: { space_id: e.space_id, nome: e.nome || '', setor: e.setor || '', desde: desde.toISOString() } });
}

// Se não tem nenhum espaço ativo, avisa o próximo nó com "vazio: true"
if (saida.length === 0) return [{ json: { vazio: true } }];
return saida;

// Junta as mensagens de todos os espaços e tira:
//  - as que o agente já processou (tabela "Mensagens processadas")
//  - as de bots e as do próprio Gestor IA (começam com 🤖)
const espacos = $('Calcular janela').all();          // 1 item por espaço, na mesma ordem
const respostas = $('Buscar mensagens no Chat').all(); // resposta da API, mesma ordem
const jaProcessadas = new Set(
  $('Já processadas').all().map(i => i.json.message_id).filter(Boolean)
);

const mensagens = [];
const erros = [];

respostas.forEach((r, i) => {
  const esp = espacos[i] ? espacos[i].json : {};

  // Se a API deu erro nesse espaço (ex.: conta saiu do espaço), registra e segue
  if (r.json.error) {
    erros.push(esp.nome + ': ' + JSON.stringify(r.json.error).slice(0, 200));
    return;
  }

  for (const m of (r.json.messages || [])) {
    if (jaProcessadas.has(m.name)) continue;
    if (m.sender && m.sender.type === 'BOT') continue;
    const texto = m.text || m.formattedText || '';
    if (texto.trim().startsWith('🤖')) continue; // mensagem do próprio Gestor IA

    // Arquivos anexados direto no Chat ou do Drive
    const anexos = (m.attachment || []).map(a => ({
      nome: a.contentName || '',
      tipo_arquivo: a.contentType || '',
      chat_resource: a.attachmentDataRef ? a.attachmentDataRef.resourceName : '',
      drive_file_id: a.driveDataRef ? a.driveDataRef.driveFileId : ''
    }));

    // Links do Drive colados no texto também contam como anexo
    for (const ann of (m.annotations || [])) {
      const meta = ann.richLinkMetadata;
      const id = meta && meta.driveLinkData && meta.driveLinkData.driveDataRef && meta.driveLinkData.driveDataRef.driveFileId;
      if (id && !anexos.some(a => a.drive_file_id === id)) {
        anexos.push({ nome: meta.uri || '', tipo_arquivo: meta.driveLinkData.mimeType || '', chat_resource: '', drive_file_id: id });
      }
    }

    mensagens.push({
      message_id: m.name,
      space_id: esp.space_id,
      space_nome: esp.nome,
      setor: esp.setor,
      thread_name: m.thread ? m.thread.name : '',
      e_resposta_dentro_de_conversa: !!m.threadReply,
      autor: m.sender ? (m.sender.displayName || m.sender.name) : '',
      autor_email: (m.sender && m.sender.email) || '',
      data: m.createTime,
      texto: texto.slice(0, 6000),
      anexos
    });
  }
});

// Mais antigas primeiro, e no máximo 20 por vez (para não estourar o limite da IA)
mensagens.sort((a, b) => (a.data < b.data ? -1 : 1));
const lote = mensagens.slice(0, 20);

return [{ json: {
  quantidade_total: mensagens.length,
  quantidade_neste_lote: lote.length,
  mensagens: lote,
  erros,
  aviso: mensagens.length > lote.length ? 'Ainda há mais mensagens. Processe este lote e chame a ferramenta de novo.' : ''
} }];
